from taf.gnb.oam.coam.cu.services.internal.agent.http_client_v1 import AGENTv1HttpClient
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage


@auto_token_refresh()
class AGENTv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = AGENTv1HttpClient(base_url=con_details.base_url,
                                              connection_alias=con_details.alias)

    def activate_cu_vnf(self, timeout):
        return self.local_client.activate_cu_vnf(timeout=timeout)

    def get_activate_cu_vnf_status(self, operation_id, timeout):
        return self.local_client.get_activate_cu_vnf_status(operation_id=operation_id, timeout=timeout)

    def forcefully_activate_cu_vnf(self, timeout):
        return self.local_client.forcefully_activate_cu_vnf(timeout=timeout)

    def get_forcefully_activate_cu_vnf_status(self, operation_id, timeout):
        return self.local_client.get_forcefully_activate_cu_vnf_status(operation_id=operation_id, timeout=timeout)

    def deactivate_cu_vnf(self, timeout):
        return self.local_client.deactivate_cu_vnf(timeout=timeout)

    def get_deactivate_cu_vnf_status(self, operation_id, timeout):
        return self.local_client.get_deactivate_cu_vnf_status(operation_id=operation_id, timeout=timeout)

    def get_cu_vnf(self, timeout):
        return self.local_client.get_cu_vnf(timeout=timeout)

    def reset_cu(self, timeout):
        return self.local_client.reset_cu(timeout=timeout)
